import marimo

__generated_with = "0.25.1"
app = marimo.App(width="full", app_title="BMW data EDA")


@app.cell
def _():
    import re
    from pathlib import Path

    import marimo as mo
    import pandas as pd
    import plotly.express as px
    from pypdf import PdfReader

    DATA = Path(__file__).resolve().parent.parent / "bmw_data"
    MODELS = {"F70": "BMW 1 Series", "G60": "BMW 5 Series", "G70": "BMW 7 Series"}
    return DATA, MODELS, PdfReader, mo, pd, px, re


@app.cell
def _(mo):
    mo.md("""
    # BMW data — exploratory analysis

    Источник: `../bmw_data` (read-only). Модели: **F70** (1 Series), **G60 / G68** (5 Series, G68 — китайская), **G70** (7 Series).

    1. Sales volumes
    2. Customer studies CN/EU 2025 (средние 0–10)
    3. Customer study US 2025 (G60 vs G70, шкала 1–7)
    4. Customer feedback (вербатимы с VFC-классификацией)
    5. Coverage: где продаём vs откуда отзывы
    6. Option lists (PDF прайсы)
    """)
    return


@app.cell
def _(mo):
    mo.md("""
    ## 1. Sales volumes
    """)
    return


@app.cell
def _(DATA, pd):
    _sheets = pd.read_excel(DATA / "sales_volumes.xlsx", sheet_name=None)
    sales = pd.concat(
        [_df.assign(model=_name) for _name, _df in _sheets.items()], ignore_index=True
    )
    sales_long = sales.melt(
        id_vars=["model", "market", "market_code"],
        value_vars=["volume_2024", "volume_2025", "volume_2030"],
        var_name="year",
        value_name="volume",
    ).assign(year=lambda d: d.year.str.removeprefix("volume_"))
    sales
    return (sales_long,)


@app.cell
def _(px, sales_long):
    px.bar(
        sales_long,
        x="market",
        y="volume",
        color="year",
        barmode="group",
        facet_col="model",
        title="Volumes by model × market (2030 = forecast)",
        height=400,
    )
    return


@app.cell
def _(sales_long):
    _p = sales_long.pivot_table(index=["model", "market_code"], columns="year", values="volume")
    _p["growth_25_30_%"] = ((_p["2030"] / _p["2025"] - 1) * 100).round(1)
    _p["share_2025_%"] = (_p["2025"] / _p.groupby(level="model")["2025"].transform("sum") * 100).round(1)
    _p
    return


@app.cell
def _(mo):
    mo.md("""
    ## 2. Customer studies — CN / EU 2025

    Лист `CN_EU_2025`: пары строк *атрибут / Mean*. Колонки = модель × страна датасета.
    """)
    return


@app.cell
def _(DATA, pd):
    _raw = pd.read_excel(DATA / "F70_G60_G68_G70_customer_studies.xlsx", sheet_name="CN_EU_2025", header=None)
    _countries = _raw.iloc[1, 1:6].ffill().tolist()
    _models = [str(m).strip() for m in _raw.iloc[2, 1:6]]
    _cols = [f"{c} · {m.split()[-1]}" for c, m in zip(_countries, _models)]
    _rows = []
    _attr = None
    for _, _r in _raw.iterrows():
        _label = _r[0]
        if pd.isna(_label):
            continue
        if _label == "Mean" and _attr is not None:
            _rows.append([_attr, *_r[1:6].astype(float)])
        else:
            _attr = str(_label).strip()
    cneu = pd.DataFrame(_rows, columns=["attribute", *_cols]).set_index("attribute")
    cneu
    return (cneu,)


@app.cell
def _(cneu, px):
    px.imshow(
        cneu,
        text_auto=".1f",
        aspect="auto",
        color_continuous_scale="RdYlGn",
        title="CN/EU mean satisfaction by attribute",
        height=max(400, 22 * len(cneu)),
    )
    return


@app.cell
def _(cneu, mo):
    _overall = cneu.loc["Overall product satisfaction"]
    _gap = (cneu.drop("Overall product satisfaction") - _overall).round(2)
    _weak = {c: _gap[c].nsmallest(5) for c in _gap.columns}
    mo.vstack(
        [
            mo.md("**Слабейшие атрибуты** (разница с overall satisfaction той же колонки):"),
            mo.hstack([mo.ui.table(_s.reset_index(), label=c, selection=None) for c, _s in _weak.items()], wrap=True),
        ]
    )
    return


@app.cell
def _(mo):
    mo.md("""
    ## 3. Customer study — US 2025 (G60 vs G70)

    Лист `US_2025`: блоки по 9 строк: атрибут, Sample total, 7 уровней (*I Hate It* … *I Love It*), доли выборки.
    Считаем: **mean score** (1–7), **top-2 box** (Delightful + I Love It), **bottom-3 box** (Hate/Failure/Unsatisfactory).
    """)
    return


@app.cell
def _(DATA, pd):
    LEVELS = ["I Hate It", "A Failure", "Unsatisfactory", "Satisfactory", "Excellent", "Delightful", "I Love It"]
    _raw = pd.read_excel(DATA / "F70_G60_G68_G70_customer_studies.xlsx", sheet_name="US_2025", header=None)
    _models = {2: "G60", 3: "G70"}
    _recs = []
    _attr = None
    for _, _r in _raw.iterrows():
        _label = _r[0]
        if pd.isna(_label):
            continue
        _label = str(_label).strip()
        if _label in LEVELS:
            for _c, _m in _models.items():
                _recs.append({"attribute": _attr, "model": _m, "level": _label, "share": float(_r[_c])})
        elif _label != "Sample total":
            _attr = _label
    us_long = pd.DataFrame(_recs)
    us_long["score"] = us_long.level.map({l: i + 1 for i, l in enumerate(LEVELS)})


    def _summ(g):
        _w = g.share.sum()
        return pd.Series(
            {
                "mean_1_7": (g.score * g.share).sum() / _w,
                "top2": g.loc[g.score >= 6, "share"].sum() / _w,
                "bottom3": g.loc[g.score <= 3, "share"].sum() / _w,
            }
        )


    us = us_long.groupby(["attribute", "model"], sort=False).apply(_summ).unstack("model")
    us.columns = [f"{a}_{m}" for a, m in us.columns]
    us["mean_diff_G70-G60"] = us.mean_1_7_G70 - us.mean_1_7_G60
    us = us.round(3)
    return LEVELS, us, us_long


@app.cell
def _(mo, us):
    mo.vstack(
        [
            mo.md(f"**{len(us)} атрибутов.** Сортируй по колонкам в таблице."),
            mo.ui.table(us.reset_index(), page_size=15, selection=None),
        ]
    )
    return


@app.cell
def _(px, us):
    _d = us["mean_diff_G70-G60"].sort_values()
    _d = _d[(_d.abs() >= _d.abs().quantile(0.8))]
    px.bar(
        _d,
        orientation="h",
        title="Наибольшие разрывы G70 − G60 (mean 1–7, top-20% по модулю)",
        height=max(400, 18 * len(_d)),
        labels={"value": "G70 − G60", "attribute": ""},
    ).update_layout(showlegend=False)
    return


@app.cell
def _(mo, us):
    us_attr = mo.ui.dropdown(options=list(us.index), value=us.index[0], label="Attribute", searchable=True)
    us_attr
    return (us_attr,)


@app.cell
def _(LEVELS, px, us_attr, us_long):
    px.bar(
        us_long[us_long.attribute == us_attr.value],
        x="level",
        y="share",
        color="model",
        barmode="group",
        category_orders={"level": LEVELS},
        title=f"US distribution: {us_attr.value}",
        height=350,
    )
    return


@app.cell
def _(mo, us):
    _cols = ["bottom3_G60", "bottom3_G70"]
    mo.hstack(
        [
            mo.ui.table(us[_c].nlargest(10).reset_index(), label=f"Most negative: {_c}", selection=None)
            for _c in _cols
        ]
    )
    return


@app.cell
def _(mo):
    mo.md("""
    ## 4. Customer feedback (`*_feedback_hackathon.xlsx`)

    Одна строка = (отзыв × VFC-категория). Один `ID` может встречаться несколько раз.
    """)
    return


@app.cell
def _(DATA, MODELS, pd):
    fb = pd.concat(
        [pd.read_excel(DATA / f"{m}_feedback_hackathon.xlsx").assign(model=m) for m in MODELS],
        ignore_index=True,
    )
    fb["Feedback Type"] = fb["Feedback Type"].fillna("(none)")
    fb["text_len"] = fb["Customer Feedback"].astype(str).str.len()
    fb["unclassified"] = fb["Vfc level2 Name"].isna() | (fb["Vfc level2 Name"] == "no_class_found")
    fb_docs = fb.drop_duplicates(["model", "ID"])
    return fb, fb_docs


@app.cell
def _(fb, fb_docs, pd):
    pd.DataFrame(
        {
            "rows": fb.groupby("model").size(),
            "unique_feedbacks": fb_docs.groupby("model").size(),
            "rows_per_feedback": (fb.groupby("model").size() / fb_docs.groupby("model").size()).round(2),
            "unclassified_rows_%": (fb.groupby("model").unclassified.mean() * 100).round(1),
            "median_text_len": fb_docs.groupby("model").text_len.median(),
            "countries": fb.groupby("model").Country.nunique(),
            "sources": fb.groupby("model").Source.nunique(),
        }
    )
    return


@app.cell
def _(fb, mo, px):
    def _mix(col, title):
        _d = fb.groupby(["model", col]).size().rename("n").reset_index()
        _d["share"] = _d.n / _d.groupby("model").n.transform("sum")
        return px.bar(_d, x="model", y="share", color=col, title=title, hover_data=["n"], height=350)


    mo.hstack(
        [
            _mix("Feedback Type", "Feedback type mix"),
            _mix("Engine Type", "Engine type mix"),
            _mix("Source", "Source mix"),
        ],
        widths="equal",
    )
    return


@app.cell
def _(fb, px):
    _d = fb.groupby(["model", "Country"]).size().rename("n").reset_index()
    px.bar(_d, x="Country", y="n", color="model", barmode="group", log_y=True, title="Rows by country (log)", height=350)
    return


@app.cell
def _(fb, px):
    _d = fb.groupby(["Source", "Feedback Type"]).size().rename("n").reset_index()
    _d["share"] = _d.n / _d.groupby("Source").n.transform("sum")
    px.bar(_d, x="Source", y="share", color="Feedback Type", title="Feedback type by source (все модели)", height=350)
    return


@app.cell
def _(fb_docs, px):
    px.histogram(
        fb_docs.assign(text_len=fb_docs.text_len.clip(upper=1500)),
        x="text_len",
        color="Source",
        facet_col="model",
        nbins=60,
        title="Длина текста отзыва (символы, clip 1500)",
        height=350,
    )
    return


@app.cell
def _(mo):
    fb_type = mo.ui.dropdown(
        options=["Defect", "Difficult to Use", "Wants", "Likes", "(none)"], value="Defect", label="Feedback type"
    )
    fb_level = mo.ui.radio(options=["Vfc level2 Name", "Vfc level2 3 Name"], value="Vfc level2 Name", label="Level")
    fb_topn = mo.ui.slider(5, 30, value=15, label="Top N")
    mo.hstack([fb_type, fb_level, fb_topn], justify="start")
    return fb_level, fb_topn, fb_type


@app.cell
def _(fb, fb_level, fb_topn, fb_type, px):
    _d = fb[(fb["Feedback Type"] == fb_type.value) & ~fb.unclassified]
    _d = _d.groupby(["model", fb_level.value]).size().rename("n").reset_index()
    _d["share_in_model_%"] = (_d.n / _d.groupby("model").n.transform("sum") * 100).round(1)
    _top = _d.sort_values("n", ascending=False).groupby("model").head(fb_topn.value)
    px.bar(
        _top,
        y=fb_level.value,
        x="share_in_model_%",
        color="model",
        facet_col="model",
        orientation="h",
        hover_data=["n"],
        title=f"Top categories — {fb_type.value}",
        height=max(450, 22 * fb_topn.value),
    ).update_yaxes(matches=None, showticklabels=True, categoryorder="total ascending").update_layout(showlegend=False)
    return


@app.cell
def _(fb, mo):
    _d = fb[~fb.unclassified]
    _p = _d.pivot_table(index="Vfc level2 Name", columns="Feedback Type", values="ID", aggfunc="count", fill_value=0)
    _p["total"] = _p.sum(axis=1)
    _neg = [c for c in ["Defect", "Difficult to Use"] if c in _p]
    _p["negative_%"] = (_p[_neg].sum(axis=1) / _p.total * 100).round(1)
    _p = _p.sort_values("total", ascending=False)
    mo.vstack(
        [
            mo.md("**VFC level2 × feedback type (все модели).** `negative_%` = Defect + Difficult to Use."),
            mo.ui.table(_p.reset_index(), page_size=15, selection=None),
        ]
    )
    return


@app.cell
def _(fb, px):
    _neg = fb[fb["Feedback Type"].isin(["Defect", "Difficult to Use"])].groupby(["model", "Engine Type"]).size()
    _all = fb.groupby(["model", "Engine Type"]).size()
    _d = (_neg / _all * 100).round(1).rename("negative_%").reset_index()
    px.bar(_d, x="model", y="negative_%", color="Engine Type", barmode="group", title="Доля Defect+DTU по типу двигателя", height=350)
    return


@app.cell
def _(mo):
    mo.md("""
    ### Browse verbatims
    """)
    return


@app.cell
def _(fb, mo):
    br_model = mo.ui.multiselect(options=sorted(fb.model.unique()), value=sorted(fb.model.unique()), label="Model")
    br_type = mo.ui.multiselect(options=sorted(fb["Feedback Type"].unique()), label="Type (empty = all)")
    br_cat = mo.ui.dropdown(
        options=["(all)", *sorted(fb["Vfc level2 Name"].dropna().unique())], value="(all)", label="VFC level2", searchable=True
    )
    br_q = mo.ui.text(label="Text contains", placeholder="e.g. screen")
    mo.hstack([br_model, br_type, br_cat, br_q], justify="start", wrap=True)
    return br_cat, br_model, br_q, br_type


@app.cell
def _(br_cat, br_model, br_q, br_type, fb, mo):
    _d = fb[fb.model.isin(br_model.value)]
    if br_type.value:
        _d = _d[_d["Feedback Type"].isin(br_type.value)]
    if br_cat.value != "(all)":
        _d = _d[_d["Vfc level2 Name"] == br_cat.value]
    if br_q.value:
        _d = _d[_d["Customer Feedback"].astype(str).str.contains(br_q.value, case=False, regex=False)]
    mo.vstack(
        [
            mo.md(f"**{len(_d)} rows / {_d.ID.nunique()} feedbacks**"),
            mo.ui.table(
                _d[["ID", "model", "Source", "Country", "Engine Type", "Feedback Type", "Vfc level2 3 Name", "Customer Feedback"]],
                page_size=20,
                selection=None,
            ),
        ]
    )
    return


@app.cell
def _(mo):
    mo.md("""
    ## 5. Coverage: продажи vs отзывы

    Доля рынка в продажах 2025 против доли отзывов из этого рынка. EU = страны Европы из отзывов.
    """)
    return


@app.cell
def _(fb_docs, pd, sales_long):
    _eu = {"GB", "SE", "FR", "DK", "FI", "NO", "ES", "DE", "IT", "NL", "BE", "AT", "CH", "PL", "PT", "IE"}
